function testHistoricalBackingCannotSubsidizeInsufficientMarginalLP() public {
    vault.migrationBudget().setLossLimits(100,300);uint256 incumbent=activatedPosition();_historicalFixture();uint256 before=vault.sharesOf(incumbent);
    uint256 entrant=_mint(bob);_callback(3);venue.setSpendBps(9800);
    vm.prank(bob);vm.expectRevert(ZZZContributionPricing.Slippage.selector);vault.activate{value:0}(entrant, poolId, 0, 100, 1, block.timestamp+100);
    assertEq(vault.sharesOf(incumbent),before);assertEq(vault.sharesOf(entrant),0);
    assertEq(t1.balanceOf(bob),100000);assertEq(address(fees).balance,0);
    assertFalse(oracle.contributionPricing().active());
}

